# Builds narration.json from script.md and data.js from results.json, and checks every spoken number.
import json, re, math
import numpy as np
txt = open("script.md").read()
KEYS = ['penalty', 'loss', 'linear', 'many', 'embed', 'resid', 'norm', 'mlp', 'attn', 'route', 'block', 'refs']
blocks = [b for b in re.split(r"\n## ", txt)[1:] if b[:1].isdigit()]
assert len(blocks) == len(KEYS), len(blocks)
def sentences(p):
    ss = re.split(r"(?<=[.!?])\s+(?=[A-Z\"“])", p); out = []
    for s in ss:
        if out and len(out[-1].split()) + len(s.split()) <= 30 and len(s.split()) < 5: out[-1] += " " + s
        else: out.append(s)
    return out
N = {}
for key, block in zip(KEYS, blocks):
    vo = block.split("**Voice-over:**")[1].split("**Reader:**")[0].replace("---", "").strip()
    paras = [p.replace("\n", " ").replace("**", "").strip() for p in vo.split("\n\n")]
    N[key] = [s for p in paras if p for s in sentences(p)]
K = json.load(open("results.json")); J = lambda k: " ".join(N[k]); r = lambda v, n=2: round(v, n)
def has(k, *ss):
    for s in ss: assert s in J(k), (k, s)
L = K['loss']; assert [r(v) for v in L['exp']] == [7.39, 2.72, 1.0, .37] and r(L['sum_exp']) == 11.48 and [r(v) for v in L['p']] == [.64, .24, .09, .03] and r(L['loss']) == .44 and [r(v) for v in L['grad']] == [-.36, .24, .09, .03] and r(L['grad_over_N'][0]) == -.06
has('loss', '7.39', '2.72', '0.37', '11.48', '0.64, 0.24, 0.09 and 0.03', '0.44', 'minus 0.36, 0.24, 0.09 and 0.03', 'minus 0.06')
LN = K['linear']; assert LN['y'] == [3, -2] and LN['GW'] == [[.5, -1], [1, -2], [-.5, 1]] and LN['GX'] == [1.25, 0, -2.25] and r(LN['W_new'][0][0]) == .45 and r(LN['W_new'][0][1]) == -.9 and r(LN['W_new'][1][0]) == .9 and r(LN['lin_before'], 2) == 3.5 and r(LN['lin_after'], 2) == 2.75 and r(LN['drop']) == .75 and LN['fro2'] == 7.5
has('linear', 'which is 3', 'minus 2', '1.25', 'minus 2.25', 'from 0.5 to 0.45', 'minus 0.9', '3.5 to 2.75', '0.75', '7.5')
M = K['many']; assert r(M['GW'][0][0]) == -.3 and r(M['GW'][0][1]) == 0 and r(M['GW'][1][0]) == -.1 and r(M['GW'][1][1]) == .3 and r(M['GW'][2][0]) == .5 and r(M['GW'][2][1]) == .3 and r(M['W_new'][0][0]) == .65 and M['check'] < 1e-12
has('many', 'minus 0.3', 'is minus 0.1', '0.1 plus 0.2 is 0.3', '0.3 plus 0.2 is 0.5', '0.65')
E_ = K['embed']; assert [r(v) for v in E_['the_row']] == [.4, -.1, .3] and E_['rows_touched'] == 4
has('embed', '0.1 plus 0.3', 'Four of the five rows change')
RS = K['resid']; assert [r(v, 1) for v in RS['branch']] == [-.1, .4] and [r(v, 1) for v in RS['gx']] == [.9, 1.4] and r(RS['residual12']) == 3.14 and RS['plain12'] < 1.1e-12
has('resid', 'minus 0.1', '0.4', '0.9 and 1.4', '10 to the minus 12', '3.14')
NM = K['norm']; assert r(NM['sq_mean'], 1) == 6.5 and r(NM['rms']) == 2.55 and [r(v) for v in NM['y']] == [1.18, -.39, 0, 1.57] and r(NM['y_dot_g']) == 2.75 and [r(v, 3) for v in NM['gx']] == [.075, .106, 0, -.030] and abs(NM['gx_dot_x']) < 1e-12
has('norm', '6.5', '2.55', '1.18, minus 0.39, 0 and 1.57', '2.75', '0.69', '0.075, 0.106, 0 and minus 0.030')
ML = K['mlp']; assert ML['scores'] == [2, -1, .5, 3] and ML['out'] == [2.5, 6.5] and ML['g_act'] == [1, -1, 0, -2] and ML['g_pre'][0] == 1 and ML['g_pre'][3] == -2 and ML['gx'] == [0, -2, 0]
has('mlp', '2, minus 1, 0.5 and 3', '2.5 and 6.5', 'minus 2, minus 4, 0', '0, minus 2, 0')
AT = K['attn']; assert [r(v) for v in AT['A'][1][:2]] == [.33, .67] and r(AT['GV'][0][0]) == 1.33 and AT['GA'][2] == [1, -1, 0] and r(AT['row2_mean']) == 0 and [r(v) for v in AT['GS'][2]] == [.33, -.33, 0] and [r(v) for v in AT['GQ'][2]] == [.24, -.24] and r(AT['sqrt_dk']) == 1.41
has('attn', '0.33 and 0.67', '1.33', '1, minus 1 and 0', '0.24 and minus 0.24', '1.41')
RT = K['route']; assert RT['a0'] == [.5, .5] and RT['gs'] == [.5, -.5] and [r(v, 3) for v in RT['a1']] == [.475, .525] and r(RT['loss1'], 3) == .451 and RT['equal_value_grad'] == [0, 0] and r(RT['attn2'][80]) == .89 and r(RT['loss'][80], 3) == .022
has('route', '0.475 and 0.525', '0.451', '0.89', '0.022', 'plus 0.5', 'minus 0.5')
assert max(K['fd'].values()) < 4e-10; has('block', '4 times ten to the minus 10')
json.dump(N, open("narration.json", "w"), indent=1)
open("data.js", "w").write("// generated by make_narration.py\nwindow.RES = {};\nwindow.RES0 = {};\nwindow.RES3 = {};\nwindow.LAB = " + json.dumps(K) + ";\n")
for k, v in N.items(): print(f"{k:10s} {len(v):2d} sentences {sum(len(s.split()) for s in v):4d} words")
tot = sum(len(s.split()) for v in N.values() for s in v); print("total", tot, "words, about", round(tot / 2.75 / 60, 1), "min")
